#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testRemoveRepeatedElementsFromArray();

void testRemoveRepeatedElementsFromArray()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // CASE 1: by id
    std::any array1 = ccxt::list{ccxt::dict {
    { std::string("id"), std::string("a") },
    { std::string("timestamp"), 1 },
    { std::string("uniq"), std::string("x1") },
}, ccxt::dict {
    { std::string("id"), std::string("b") },
    { std::string("timestamp"), 2 },
    { std::string("uniq"), std::string("x2") },
}, ccxt::dict {
    { std::string("id"), std::string("a") },
    { std::string("timestamp"), 3 },
    { std::string("uniq"), std::string("x3") },
}, ccxt::dict {
    { std::string("id"), std::string("c") },
    { std::string("timestamp"), 1 },
    { std::string("uniq"), std::string("x4") },
}};
    std::any res1 = exchange.removeRepeatedElementsFromArray(array1, false);
    std::any res1Length = getArrayLength(res1);
    assertTrue(isEqual(res1Length, 3));
    assertTrue(isEqual(::getValue(::getValue(res1, 0), std::string("uniq")), std::string("x1")));
    assertTrue(isEqual(::getValue(::getValue(res1, 1), std::string("uniq")), std::string("x2")));
    assertTrue(isEqual(::getValue(::getValue(res1, 2), std::string("uniq")), std::string("x4")));
    // CASE 2: by timestamp
    std::any array2 = ccxt::list{ccxt::dict {
    { std::string("id"), std::any{} },
    { std::string("timestamp"), 1 },
    { std::string("uniq"), std::string("x1") },
}, ccxt::dict {
    { std::string("id"), std::any{} },
    { std::string("timestamp"), 2 },
    { std::string("uniq"), std::string("x2") },
}, ccxt::dict {
    { std::string("id"), std::any{} },
    { std::string("timestamp"), 1 },
    { std::string("uniq"), std::string("x3") },
}, ccxt::dict {
    { std::string("id"), std::any{} },
    { std::string("timestamp"), 3 },
    { std::string("uniq"), std::string("x4") },
}};
    std::any res2 = exchange.removeRepeatedElementsFromArray(array2, true);
    std::any res2Length = getArrayLength(res2);
    assertTrue(isEqual(res2Length, 3));
    assertTrue(isEqual(::getValue(::getValue(res2, 0), std::string("uniq")), std::string("x1")));
    assertTrue(isEqual(::getValue(::getValue(res2, 1), std::string("uniq")), std::string("x2")));
    assertTrue(isEqual(::getValue(::getValue(res2, 2), std::string("uniq")), std::string("x4")));
    // CASE 3: by timestamp index (used in ohlcv)
    std::any array3 = ccxt::list{ccxt::list{555, 1, 1, std::string("x1")}, ccxt::list{666, 1, 1, std::string("x2")}, ccxt::list{555, 1, 1, std::string("x3")}};
    std::any res3 = exchange.removeRepeatedElementsFromArray(array3, true);
    assertTrue(isEqual(getArrayLength(res3), 2));
    assertTrue(isEqual(::getValue(::getValue(res3, 0), 3), std::string("x1")));
    assertTrue(isEqual(::getValue(::getValue(res3, 1), 3), std::string("x2")));
}

